/// Treapのpriorityを作るための乱数生成器
/// priorityが十分にバラければTreapの高さの期待値はO(logN)
#[derive(Clone, Copy)]
struct TreapRandom {
    seed: u64,
} // end of struct

impl TreapRandom {
    /// 初期seedを指定して構築
    #[inline(always)]
    fn new(seed: u64) -> Self {
        return Self {
            seed,
        };
    } // end of constructor

    /// splitmix64風の乱数の値を返す
    /// 返り値が大きいほどTreapの上にくるMaxHeap
    /// https://www.hanachiru-blog.com/entry/2023/08/25/120000
    #[inline(always)]
    fn next_u64(&mut self) -> u64 {
        self.seed = self.seed.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.seed;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        return z ^ (z >> 31);
    } // end of method
} // end of impl TreapRandom

