    /// キーが存在するか
    #[inline(always)]
    pub fn contains(&self, key: &T) -> bool {
        return self.get(key).is_some();
    } // end of method

    /// キーの個数を返す
    #[inline(always)]
    pub fn count_of(&self, key: &T) -> usize {
        let mut current = self.root.as_ref();
        while let Some(node) = current {
            match (self.compare)(key, &node.key) {
                Ordering::Less => current = node.left.as_ref(),
                Ordering::Greater => current = node.right.as_ref(),
                Ordering::Equal => return node.node_count,
            }
        }
        return 0;
    } // end of method

    /// キーが存在するなら, 木の中に保存されているキーへの参照を返す
    #[inline(always)]
    pub fn get(&self, key: &T) -> Option<&T> {
        let mut current = self.root.as_ref();
        while let Some(node) = current {
            match (self.compare)(key, &node.key) {
                Ordering::Less => current = node.left.as_ref(),
                Ordering::Greater => current = node.right.as_ref(),
                Ordering::Equal => return Some(&node.key),
            }
        }
        return None;
    } // end of method

    /// 0-indexedで, 重複込みのindex番目のキーを返す
    #[inline(always)]
    pub fn get_at(&self, mut index: usize) -> Option<&T> {
        if self.count() <= index {
            return None;
        }

        let mut current = self.root.as_ref();
        while let Some(node) = current {
            // 左にある？
            let left_size = Self::size_of(&node.left);
            if index < left_size {
                current = node.left.as_ref();
                continue;
            }

            // 自分の範囲？
            index -= left_size;
            if index < node.node_count {
                return Some(&node.key);
            }

            // なければ右だね
            index -= node.node_count;
            current = node.right.as_ref();
        }
        return None;
    } // end of method

    /// 0-indexedで, ユニークキーとしてindex番目のキーを返す
    #[inline(always)]
    pub fn get_unique_at(&self, mut index: usize) -> Option<&T> {
        if self.unique_count <= index {
            return None;
        }

        let mut current = self.root.as_ref();
        while let Some(node) = current {
            let left_unique_size = Self::unique_size_of(&node.left);
            if index < left_unique_size {
                current = node.left.as_ref();
                continue;
            }

            index -= left_unique_size;
            if index == 0 {
                return Some(&node.key);
            }

            index -= 1;
            current = node.right.as_ref();
        }
        return None;
    } // end of 

    /// key以上の最小のキーを返す
    #[inline(always)]
    pub fn lower_bound(&self, key: &T) -> Option<&T> {
        let mut current = self.root.as_ref();
        let mut answer = None;

        while let Some(node) = current {
            match (self.compare)(key, &node.key) {
                Ordering::Less | Ordering::Equal => {
                    answer = Some(&node.key);
                    current = node.left.as_ref();
                }
                Ordering::Greater => {
                    current = node.right.as_ref();
                }
            }
        }
        return answer;
    } // end of method

